#include <iostream>
#include <vector>
#include <list>
#include <string>
using namespace std;

template<typename K, typename V>
class HashTable {
    vector<list<pair<K,V>>> buckets;
    size_t hash(const K& key) { return std::hash<K>{}(key) % buckets.size(); }
public:
    HashTable(size_t size = 8) : buckets(size) {}

    void insert(const K& key, const V& val) {
        auto& bucket = buckets[hash(key)];
        for (auto& p : bucket) { if (p.first == key) { p.second = val; return; } }
        bucket.push_back({key, val});
    }

    V* get(const K& key) {
        for (auto& p : buckets[hash(key)])
            if (p.first == key) return &p.second;
        return nullptr;
    }
};

int main() {
    HashTable<string, int> ht;
    ht.insert("apple", 5);
    ht.insert("banana", 3);
    ht.insert("cherry", 8);

    int* v = ht.get("banana");
    if (v) cout << "banana: " << *v << endl;
    v = ht.get("grape");
    if (!v) cout << "grape: not found" << endl;
    return 0;
}
